const total = 10n;
const parts = 4n;

console.log((total / parts) * parts);
console.log(total % parts);
console.log(typeof (total / parts));
console.log(total > 9.5);
console.log(total === 10);

try {
  console.log(Math.max(total, parts));
} catch (error) {
  console.log(error.name);
}
